3	(function setupBookingPage() {
4	  const NO_REPLY = 'Could not reach the server.';
5	  const FALLBACK_ERROR = 'Request failed.';
6	  const SUCCESS_STATUS = { GET: 200, POST: 201, DELETE: 204 };
7	
8	  const form = document.getElementById('booking-form');
9	  const roomSelect = document.getElementById('room');
10	  const titleInput = document.getElementById('title');
11	  const dateInput = document.getElementById('date');
12	  const startInput = document.getElementById('start');
13	  const endInput = document.getElementById('end');
14	  const bookButton = document.getElementById('book');
15	  const filterDate = document.getElementById('filter-date');
16	  const showAllButton = document.getElementById('show-all');
17	  const bookingList = document.getElementById('booking-list');
18	  const errorBox = document.getElementById('error');
19	
20	  let listGeneration = 0;
21	
22	  // Resolves to { ok, status, body } when a reply arrived, or null when there was none.
23	  // A non-204 reply whose body is not JSON counts as no reply.
24	  async function request(method, url, payload) {
25	    const options = { method };
26	    if (payload !== undefined) {
27	      options.headers = { 'Content-Type': 'application/json' };
28	      options.body = JSON.stringify(payload);
29	    }
30	    try {
31	      const reply = await fetch(url, options);
32	      const body = reply.status === 204 ? undefined : await reply.json();
33	      return { ok: reply.status === SUCCESS_STATUS[method], status: reply.status, body };
34	    } catch {
35	      // Network failure or unreadable body: the caller shows the no-reply message.
36	      return null;
37	    }
38	  }
39	
40	  function errorMessage(body) {
41	    const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
42	    return isObject && typeof body.error === 'string' ? body.error : FALLBACK_ERROR;
43	  }
44	
45	  function showError(text) {
46	    errorBox.textContent = text;
47	  }
48	
49	  function showOutcomeError(result) {
50	    showError(result === null ? NO_REPLY : errorMessage(result.body));
51	  }
52	
53	  async function loadRooms() {
54	    const result = await request('GET', '/api/rooms');
55	    if (result === null || !result.ok) {
56	      showOutcomeError(result);
57	      return;
58	    }
59	    const options = result.body.rooms.map((name) => {
60	      const option = document.createElement('option');
61	      option.value = name;
62	      option.textContent = name;
63	      return option;
64	    });
65	    roomSelect.replaceChildren(...options);
66	  }
67	
68	  function bookingItem(booking) {
69	    const item = document.createElement('li');
70	    const cancel = document.createElement('button');
71	    cancel.type = 'button';
72	    cancel.textContent = 'Cancel';
73	    cancel.addEventListener('click', () => cancelBooking(booking.id, cancel));
74	    const text = `${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`;
75	    item.append(text, cancel);
76	    return item;
77	  }
78	
79	  function emptyItem() {
80	    const item = document.createElement('li');
81	    item.append('No bookings.');
82	    return item;
83	  }
84	
85	  async function loadList() {
86	    listGeneration += 1;
87	    const generation = listGeneration;
88	    const filter = filterDate.value;
89	    const url = filter === '' ? '/api/bookings' : `/api/bookings?date=${filter}`;
90	    const result = await request('GET', url);
91	    if (generation !== listGeneration) {
92	      return;
93	    }
94	    if (result === null || !result.ok) {
95	      showOutcomeError(result);
96	      return;
97	    }
98	    const bookings = result.body.bookings;
99	    const items = bookings.length === 0 ? [emptyItem()] : bookings.map(bookingItem);
100	    bookingList.replaceChildren(...items);
101	  }
102	
103	  async function cancelBooking(id, button) {
104	    button.disabled = true;
105	    const result = await request('DELETE', `/api/bookings/${id}`);
106	    button.disabled = false;
107	    if (result === null) {
108	      showError(NO_REPLY);
109	      return;
110	    }
111	    showError(result.ok ? '' : errorMessage(result.body));
112	    loadList();
113	  }
114	
115	  async function submitBooking(event) {
116	    event.preventDefault();
117	    if (bookButton.disabled) {
118	      return;
119	    }
120	    bookButton.disabled = true;
121	    const payload = {
122	      room: roomSelect.value,
123	      title: titleInput.value,
124	      date: dateInput.value,
125	      start: startInput.value,
126	      end: endInput.value,
127	    };
128	    const result = await request('POST', '/api/bookings', payload);
129	    bookButton.disabled = false;
130	    if (result === null || !result.ok) {
131	      showOutcomeError(result);
132	      return;
133	    }
134	    titleInput.value = '';
135	    showError('');
136	    loadList();
137	  }
138	
139	  function showAll() {
140	    filterDate.value = '';
141	    loadList();
142	  }
143	
144	  form.addEventListener('submit', submitBooking);
145	  filterDate.addEventListener('change', () => loadList());
146	  showAllButton.addEventListener('click', showAll);
147	
148	  loadRooms();
149	  loadList();
150	})();
